// Component registry: maps world-layout `component` names to React components.
// Library components come from src/library-index.ts (generated by asset-library.py use / new-project.py).
// Project-only components go in src/project-assets/ and are registered below.
import type React from 'react';
import * as Library from '../library-index';
import * as ProjectAssets from '../project-assets';

type AnyComponent = React.ComponentType<Record<string, unknown>>;

const isComponent = (name: string, v: unknown) => typeof v === 'function' && /^[A-Z]/.test(name);

export const registry: Record<string, AnyComponent> = Object.fromEntries(
  [...Object.entries(Library), ...Object.entries(ProjectAssets)].filter(([k, v]) => isComponent(k, v)),
) as Record<string, AnyComponent>;

export function getComponent(name: string): AnyComponent {
  const c = registry[name];
  if (!c) throw new Error(`World layout references unknown component "${name}". Add it with asset-library.py use, or create it in src/project-assets/.`);
  return c;
}
